/* Audio inspector: existing bound controls are moved intact into a focused workspace. */
const previousAudioInspector=renderInspector;
let silenceSettings={thresholdDb:-38,minimum:.35,padding:.08};
renderInspector=function(){
 previousAudioInspector();const c=current(),root=$('#inspector-content');root.classList.toggle('audio-workspace',c?.track==='audio');if(c?.track!=='audio')return;
 const sections=[...root.children],find=title=>sections.find(s=>s.querySelector('h3')?.textContent===title);
 const hero=sections[0];hero.classList.add('audio-hero');hero.querySelector('h3').textContent='Selected audio';
 hero.insertAdjacentHTML('beforeend',`<div class="audio-meta"><span>${c.duration.toFixed(2)}s</span><span>${c.audioMuted?'Muted':c.audioRole==='voice'?'Voiceover':c.audioRole==='music'?'Music':'Audio'}</span><span>${c.speed}×</span></div><canvas class="audio-overview" width="640" height="88" aria-label="Selected audio waveform"></canvas><div class="audio-quick"><button class="secondary" id="audio-split">✂ Split here</button><button class="secondary" id="audio-silence-open">Remove silence</button><button class="secondary" id="audio-open-editor">↔ Edit waveform range</button></div>`);
 const sound=find('Sound tools'),level=find('Audio'),fades=find('Fades'),timing=find('Timing');
 if(level){level.querySelector('h3').textContent='Volume & gain';hero.after(level);const gain=sound?.querySelector('[data-enhance="gainDb"]')?.closest('label');if(gain)level.append(gain);const mute=sound?.querySelector('#mute-clip');if(mute)level.append(mute);}if(fades){if(level)level.after(fades);else hero.after(fades);}if(sound){sound.querySelector('h3').textContent='Voice, music & effects';const details=document.createElement('details');details.className='audio-mix-details inspector-section';details.innerHTML='<summary>Voice, music & effects</summary>';details.append(sound);root.append(details);}
 const silence=document.createElement('details');silence.className='inspector-section silence-panel';silence.innerHTML=`<summary>Remove silence <span class="badge">Local</span></summary><p class="small-help">Find quiet gaps and join the remaining audio. Video and other clips keep their timing. Undo restores the original.</p><label class="field">Quiet threshold · dB<input id="silence-threshold" type="number" min="-70" max="-10" step="1" value="${silenceSettings.thresholdDb}"></label><label class="field">Minimum gap · sec<input id="silence-minimum" type="number" min=".1" max="5" step=".05" value="${silenceSettings.minimum}"></label><label class="field">Keep padding · sec<input id="silence-padding" type="number" min="0" max=".5" step=".01" value="${silenceSettings.padding}"></label><button id="analyze-silence" class="secondary wide">Analyze selected audio</button><p id="silence-result" role="status" class="small-help">Original media stays untouched.</p><button id="apply-silence" class="primary wide" disabled>Remove quiet gaps</button>`;(fades||level||hero).after(silence);
 const advanced=document.createElement('details');advanced.className='inspector-section audio-advanced';advanced.innerHTML='<summary>Timing & advanced</summary>';root.append(advanced);if(timing)advanced.append(timing);for(const section of sections)if(![hero,sound,level,fades,timing].includes(section))advanced.append(section);
 const canvas=hero.querySelector('canvas'),fingerprint=()=>JSON.stringify(current());const initial=fingerprint();let plan=null,analysisRevision=0;
 decodeAudioAsset(assets.get(c.assetId)).then(buffer=>{if(canvas.isConnected)drawWaveform(canvas,c,buffer);}).catch(()=>{canvas.setAttribute('aria-label','Waveform unavailable');});
 $('#audio-split').onclick=()=>$('#split').click();
 $('#audio-silence-open').onclick=()=>{silence.open=true;silence.scrollIntoView?.({block:'nearest',behavior:'smooth'});};
 const apply=$('#apply-silence'),result=$('#silence-result'),analyze=$('#analyze-silence');
 const inputs=['threshold','minimum','padding'].map(k=>$('#silence-'+k));
 inputs.forEach(input=>input.oninput=()=>{analysisRevision++;plan=null;apply.disabled=true;result.textContent='Settings changed. Analyze again.';});
 analyze.onclick=async()=>{
  if(!requireEditable())return;const values=inputs.map(input=>Number(input.value));if(inputs.some(input=>!input.checkValidity()||input.value==='')||!values.every(Number.isFinite))return toast('Enter valid silence settings.');
  silenceSettings={thresholdDb:values[0],minimum:values[1],padding:values[2]};const revision=++analysisRevision;analyze.disabled=true;result.textContent='Analyzing on this device…';
  try{const buffer=await decodeAudioAsset(assets.get(c.assetId));if(!silence.isConnected||initial!==fingerprint()||revision!==analysisRevision)return;plan=CutlineAudioEditing.analyze(buffer,c,silenceSettings);result.textContent=plan.allSilent?'All audio is below this threshold. Lower the threshold and analyze again.':plan.gaps.length?`${plan.gaps.length} quiet gaps · ${plan.removed.toFixed(2)}s removed · ${(c.duration-plan.removed).toFixed(2)}s remaining`:'No quiet gaps found. Try a higher threshold or shorter minimum gap.';const tiny=plan.retained.some(part=>part.duration<.05);if(tiny)result.textContent='This would leave pieces under 0.05s. Increase padding and analyze again.';apply.disabled=plan.allSilent||!plan.gaps.length||tiny;
   drawWaveform(canvas,c,buffer);const ctx=canvas.getContext('2d');ctx.fillStyle='#f1af5266';for(const gap of plan.gaps)ctx.fillRect(gap.start/c.duration*canvas.width,0,(gap.end-gap.start)/c.duration*canvas.width,canvas.height);
  }catch(e){result.textContent=e.message;}finally{if(analyze.isConnected)analyze.disabled=false;}
 };
 apply.onclick=()=>{if(!plan||plan.allSilent||!plan.gaps.length||plan.retained.some(part=>part.duration<.05)||!requireEditable())return;if(initial!==fingerprint())return toast('Audio changed. Analyze it again.');const pieces=CutlineAudioEditing.segments(c,plan,Model.sliceClip,uid);stop();checkpoint();const index=project.clips.indexOf(c);project.clips.splice(index,1,...pieces);selected=pieces[0].id;commit();toast(`Removed ${plan.removed.toFixed(2)} seconds of silence. Undo is available.`);};
 if(clipLocked(c))$$('button,input',root).forEach(el=>el.disabled=true);
};
